mapper.insert:
INSERT INTO AIRPORT (
iata_code, airport_name, country, timezone, region_id, flight_type, is_active
) VALUES (
#{iataCode}, #{airportName}, #{country}, #{timezone}, #{regionId}, #{flightType},
NVL(#{isActive}, 'Y')
)

mapper.update:
UPDATE AIRPORT
SET is_active = #{isActive}
WHERE airport_id = #{airportId}
